"""Run-scoped training budget; original v27 code and six-attempt guards are reused."""
from contextlib import contextmanager
from copy import deepcopy
from pathlib import Path

from src.skill_evolution.v27.benchmarks.lmb import protocol as p
from src.skill_evolution.v27.benchmarks.lmb.adapter import LMBAdapter

HERE = Path(__file__).resolve().parent
ROOT = HERE.parents[4]
PROMPTS = frozenset(('grouping.md', 'diagnosis.md', 'preconditioner.md', 'editor.md', 'replay.md'))
OLD_LIMIT = 'per-request output limit of 49,152 tokens'
NEW_LIMIT = 'per-request output limit of 65,536 tokens'


def verify_resources():
    for name in PROMPTS:
        source = ROOT/'src/skill_evolution/v27/benchmarks/lmb/prompts'/name
        original = source.read_text()
        assert original.count(OLD_LIMIT) == 1
        assert (HERE/'training_prompts'/name).read_text() == original.replace(OLD_LIMIT, NEW_LIMIT)


class TrainingAdapter(LMBAdapter):
    def resource(self, key):
        if key in PROMPTS:
            return HERE/'training_prompts'/key
        return super().resource(key)

    @staticmethod
    def execution_context(background):
        return p.execution_context(background)

    def frozen_files(self):
        files = super().frozen_files()
        for path in [HERE/'training_budget.py', HERE/'run_pipeline.py', HERE/'training_config.json',
                     *sorted((HERE/'training_prompts').glob('*.md'))]:
            files[str(path.relative_to(ROOT))] = path.read_text()
        return files


@contextmanager
def training_budget():
    """Enter before workers start; restore only after all training workers join."""
    verify_resources()
    original_actor = p.ACTOR
    original_context = p.execution_context
    assert original_actor['max_tokens'] == 49152
    assert original_actor['request_attempts_total'] == 6
    p.ACTOR = {**deepcopy(original_actor), 'max_tokens': 65536}

    def context(background):
        value = original_context(background)
        assert value.count(OLD_LIMIT) == 1
        return value.replace(OLD_LIMIT, NEW_LIMIT)

    p.execution_context = context
    try:
        yield
    finally:
        p.ACTOR = original_actor
        p.execution_context = original_context
